class Solution:
    def constructArray(self, n: int, k: int) -> List[int]:
        result = []
        left, right = 1, n
        while left <= right:
            if k % 2:
                result.append(left)
                left += 1
            else:
                result.append(right)
                right -= 1
            if k > 1:
                k -= 1
        return result

class Solution:
    def findKthNumber(self, m, n, k):
        def count(x):
            return sum(min(x//i, n) for i in range(1,m+1))

        L, R, mid, ans = 0, m*n, 0, 0
        while L <= R:
            mid = (L + R) >> 1
            if count(mid) < k:
                L = mid + 1
            else:
                R, ans = mid - 1, mid
        return ans

class Solution:
    def maximumSwap(self, num: int) -> int:
        digits = list(str(num))
        left, right = 0, 0
        max_idx = len(digits)-1
        for i in reversed(range(len(digits))):
            if digits[i] > digits[max_idx]:
                max_idx = i
            elif digits[max_idx] > digits[i]:
                left, right = i, max_idx
        digits[left], digits[right] = digits[right], digits[left]
        return int("".join(digits))

class Solution:
    def flipLights(self, n: int, m: int) -> int:
        # Reduce n to at most 3, since any action performed more than 3 times
        # will result in a pattern that has already been counted
        n = min(n, 3)
        if m == 0:
            return 1
        elif m == 1:
            # For m=1, there are only 2 outcomes for n=1, 3 outcomes for n=2, and 4 outcomes for n=3
            return [2, 3, 4][n - 1]
        elif m == 2:
            # For m=2, there are only 2 outcomes for n=1, 4 outcomes for n=2, and 7 outcomes for n=3
            return [2, 4, 7][n - 1]
        else:
            # For m>=3, there are only 2 outcomes for n=1, 4 outcomes for n=2, and 8 outcomes for n=3
            return [2, 4, 8][n - 1]

