class Solution:
    def judgePoint24(self, cards: List[int]) -> bool:
        return self.allComputeWays(cards, 4, 24)

    def allComputeWays(self, nums, l, target):
        if l == 1:
            if abs(nums[0] - target) <= 1e-6:
                return True
            return False
        for first in range(l):
            for second in range(first + 1, l):
                tmp1, tmp2 = nums[first], nums[second]
                nums[second] = nums[l - 1]

                nums[first] = tmp1 + tmp2
                if self.allComputeWays(nums, l - 1, target):
                    return True
                nums[first] = tmp1 - tmp2
                if self.allComputeWays(nums, l - 1, target):
                    return True
                nums[first] = tmp2 - tmp1
                if self.allComputeWays(nums, l - 1, target):
                    return True
                nums[first] = tmp1 * tmp2
                if self.allComputeWays(nums, l - 1, target):
                    return True
                if tmp2:
                    nums[first] = tmp1 / tmp2
                    if self.allComputeWays(nums, l - 1, target):
                        return True
                if tmp1:
                    nums[first] = tmp2 / tmp1
                    if self.allComputeWays(nums, l - 1, target):
                        return True
                nums[first], nums[second] = tmp1, tmp2
        return False

from operator import add, sub, mul, truediv
from fractions import Fraction

class Solution:
    def judgePoint24(self, nums):
        if len(nums) == 1:
            return abs(nums[0]-24) < 1e-6
        ops = [add, sub, mul, truediv]
        for i in range(len(nums)):
            for j in range(len(nums)):
                if i == j:
                    continue
                next_nums = [nums[k] for k in range(len(nums)) if i != k != j]
                for op in ops:
                    if ((op is add or op is mul) and j > i) or \
                       (op == truediv and nums[j] == 0):
                        continue
                    next_nums.append(op(nums[i], nums[j]))
                    if self.judgePoint24(next_nums):
                        return True
                    next_nums.pop()
        return False

class Solution:
    def validPalindrome(self, s: str) -> bool:
        has_deleted = False

        def compare(s, has_deleted):

            if len(s) <= 1:
                return True

            if s[0] == s[-1]:
                return compare(s[1:-1], has_deleted)
            else:
                if not has_deleted:
                    return compare(s[1:], True) or compare(s[:-1], True)
                else:
                    return False

        return compare(s, has_deleted)

class Solution:
    def validPalindrome(self, s: str) -> bool:
        def validPalindrome(s, left, right):
            while left < right:
                if s[left] != s[right]:
                    return False
                left, right = left+1, right-1
            return True

        left, right = 0, len(s)-1
        while left < right:
            if s[left] != s[right]:
                return validPalindrome(s, left, right-1) or validPalindrome(s, left+1, right)
            left, right = left+1, right-1
        return True
